head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#input1', 'key-sequence', {
        sequence: '1'
    });
}
scwin.setSimulate33 = function() {
    scwin.simulateWrapper('#input1', 'key-combo', {
        combo: 'delete'
    });
}
scwin.setSimulate1_2 = function() {
    scwin.simulateWrapper('#input1', 'key-sequence', {
        sequence: '1234'
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#input13', 'key-sequence', {
        sequence: '1'
    });
}
scwin.setSimulate2_2 = function() {
    scwin.simulateWrapper('#input13', 'key-sequence', {
        sequence: '1234'
    });
}
scwin.setSimulate3 = function() {
    scwin.simulateWrapper('#input11', 'key-sequence', {
        sequence: '1'
    });
}
scwin.setSimulate3_2 = function() {
    scwin.simulateWrapper('#input11', 'key-sequence', {
        sequence: '1234'
    });
}
scwin.setSimulate4 = function() {
    scwin.simulateWrapper('#input14', 'key-sequence', {
        sequence: '1'
    });
}
scwin.setSimulate4_2 = function() {
    scwin.simulateWrapper('#input14', 'key-sequence', {
        sequence: '1234'
    });
}
scwin.setSimulate5 = function() {
    scwin.simulateWrapper('#input12', 'key-sequence', {
        sequence: '1'
    });
}
scwin.setSimulate5_2 = function() {
    scwin.simulateWrapper('#input12', 'key-sequence', {
        sequence: '12345'
    });
}
scwin.setSimulate6 = function() {
    scwin.simulateWrapper('#input15', 'key-sequence', {
        sequence: '1'
    });
}
scwin.setSimulate6_2 = function() {
    scwin.simulateWrapper('#input15', 'key-sequence', {
        sequence: '12345'
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1500");
    //maskFormat = "reverse" displayFormat = "00.00"
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input2').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input1').getValue() == '00.01'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('input1').setValue('')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1_2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input2').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input1').getValue() == '12.34'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //maskFormat = "default" displayFormat = "00.00"
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input2').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input13').getValue() == '10.00'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('input13').setValue('')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2_2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input2').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input13').getValue() == '12.34'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //maskFormat = "reverse" displayFormat = "##.##"
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate3()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input2').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input11').getValue() == '1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('input11').setValue('')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate3_2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input2').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input11').getValue() == '12.34'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //maskFormat = "default" displayFormat = "##.##"
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate4()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input2').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input14').getValue() == '1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('input14').setValue('')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate4_2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input2').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input14').getValue() == '12.34'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //maskFormat = "reverse" displayFormat = "##0.00" 에 12345
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate5()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input2').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input12').getValue() == '0.01'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('input12').setValue('')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate5_2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input2').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input12').getValue() == '123.45'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //maskFormat = "default" displayFormat = "000##" 12345 입력 
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate6()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input2').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input15').getValue() == '100'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('input15').setValue('')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate6_2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input2').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input15').getValue() == '12345'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
